int main(void) {
    char text[] = "ABCDEFGH";
    char *left = text;
    char *right = text + strlen(text) - 1;
    while (left < right) {
        char temp = *left;
        *left++ = *right;
        *right-- = temp;
    }
    for (int i = 1; i < (int)strlen(text); i += 2)
        putchar(text[i]);
    return 0;
}

#include <stdio.h>
#include <ctype.h>
int main(void) {
    char text[] = "It is 8";
    for (int i = 0; text[i]; i++) {
        char c = text[i];
        if (isupper((unsigned char)c))
            putchar('A' + (c - 'A' + 5) % 26);
        else if (islower((unsigned char)c))
            putchar('a' + (c - 'a' + 10) % 26);
        else if (isdigit((unsigned char)c))
            putchar('0' + (c - '0' + 3) % 10);
        else
            putchar(c);
    }
    return 0;
}

